haar-cascade.pseudocode:
def integral(img):  # ii[y][x] = 왼쪽 위 영역 합
    h, w = len(img), len(img[0])
    ii = [[0] * (w + 1) for _ in range(h + 1)]
    for y in range(h):
        for x in range(w):
            ii[y + 1][x + 1] = (img[y][x] + ii[y][x + 1]
                                + ii[y + 1][x] - ii[y][x])
    return ii

def rect_sum(ii, x, y, w, h):  # 4번 참조로 O(1)
    return (ii[y + h][x + w] - ii[y][x + w]
            - ii[y + h][x] + ii[y][x])

def cascade(window, stages):
    for stage in stages:  # 단계별 강분류기
        if stage.score(window) < stage.threshold:
            return False  # 조기 기각 → 고속
    return True  # 모든 단계 통과 → 얼굴

hamiltonian-path-problem.pseudocode:
def has_hamiltonian_path(n, adj):
    # n 정점, adj[u] = u의 이웃 집합. 백트래킹 (지수)
    def backtrack(v, visited):
        if len(visited) == n:  # 모든 정점 방문
            return True
        for w in adj[v]:
            if w not in visited:
                visited.add(w)
                if backtrack(w, visited):
                    return True
                visited.remove(w)  # 되돌리기
        return False

    return any(backtrack(s, {s}) for s in range(n))

hard-link.pseudocode:
def link(fs, src, dst):
    ino = fs.lookup(src)  # 원본의 inode
    if ino.is_dir:
        raise OSError('디렉터리 하드 링크 금지')  # 순환 방지
    if fs.device(dst) != ino.device:
        raise OSError('EXDEV: 다른 파일시스템')
    fs.add_entry(dst, ino.number)  # 새 이름 → 같은 inode
    ino.nlink += 1

def unlink(fs, path):
    ino = fs.lookup(path)
    fs.remove_entry(path)
    ino.nlink -= 1
    if ino.nlink == 0 and ino.open_count == 0:
        fs.free(ino)  # 블록·inode 반납

harmonic-mean.pseudocode:
def harmonic_mean(values):
    n = len(values)
    return n / sum(1.0 / x for x in values)

def f1_score(precision, recall):
    if precision + recall == 0:
        return 0.0
    # 정밀도·재현율의 조화평균
    return 2 * precision * recall / (precision + recall)

# 예: P=1.0, R=0.0 → F1=0 (낮은 쪽에 끌림)
# P=0.6, R=0.6 → F1=0.6

hash-based-signature.pseudocode:
def keygen():  # Lamport 일회용 서명 (256비트)
    sk = [[rand256(), rand256()] for _ in range(256)]
    pk = [[H(a), H(b)] for a, b in sk]
    return sk, pk

def sign(sk, msg):
    d = bits(H(msg))  # 다이제스트 256비트
    return [sk[i][d[i]] for i in range(256)]  # 비트별 공개

def verify(pk, msg, sig):
    d = bits(H(msg))
    return all(H(sig[i]) == pk[i][d[i]]
               for i in range(256))

# 같은 키로 두 번 서명하면 비밀 절반 이상 노출 → 위조
# 머클 트리(XMSS)로 다수 일회용 키를 하나의 공개키로 묶음

hash-collision.pseudocode:
def lp_insert(table, key, h):  # 선형 조사 개방 주소법
    m = len(table)
    for step in range(m):
        j = (h(key) + step) % m  # 충돌 시 다음 칸
        if table[j] is None or table[j] == key:
            table[j] = key
            return j
    raise OverflowError('테이블 가득 참')

def lp_search(table, key, h):
    m = len(table)
    for step in range(m):
        j = (h(key) + step) % m
        if table[j] is None:
            return -1  # 빈 칸 도달 → 키 없음
        if table[j] == key:
            return j
    return -1

hash-join.pseudocode:
def hash_join(build, probe, bkey, pkey):
    # 1) Build: 작은 입력으로 메모리 해시 테이블 생성
    table = {}
    for r in build:
        table.setdefault(r[bkey], []).append(r)
    # 2) Probe: 큰 입력을 한 번 스캔하며 등치 매칭
    for s in probe:
        for r in table.get(s[pkey], []):
            yield {**r, **s}

def grace_hash_join(build, probe, bkey, pkey, n):
    # 메모리 초과 시: 같은 해시로 n개 파티션 분할
    bp = [[] for _ in range(n)]
    pp = [[] for _ in range(n)]
    for r in build:
        bp[hash(r[bkey]) % n].append(r)
    for s in probe:
        pp[hash(s[pkey]) % n].append(s)
    for i in range(n):  # 같은 번호 파티션끼리만 조인
        yield from hash_join(bp[i], pp[i], bkey, pkey)
